#!/usr/bin/env python3
"""
installer_console_accompagnement_v1.py — Console d'accompagnement (v2a)
  1. Installe app/api/console_accompagnement.py (nouveau module)
  2. Installe data/refus_par_pays_v1.json (chiffres sourcés)
  3. Branche la console dans ui.py (import + bloc admin, ancres exactes)
PRÉREQUIS : installer_moteur_plans_v1 + patch_branchement_moteur_plans_v1
déjà appliqués (la console s'insère après le bloc moteur_plans).
Auto-vérifiant : SHA-256, ast.parse, json.loads, .bak, restauration.
Usage : python3 installer_console_accompagnement_v1.py
"""
import ast, base64, hashlib, json, shutil, sys
from datetime import datetime
from pathlib import Path

RACINE = Path.home() / "mobilite-ia"
UI = RACINE / "app/api/ui.py"

FICHIERS = {
    "app/api/console_accompagnement.py": {
        "sha256": "a9cbbc7dfa0b850a56a3df3a11963d0a8126239a2f458e3648a54a8b3feab60a",
        "b64": "",
        "verif": "python",
    },
    "data/refus_par_pays_v1.json": {
        "sha256": "ccd8db12ac6ee8b73d39ee6f66b22cdebc803141525daafd51dde4a03ed62a46",
        "b64": "",
        "verif": "json",
    },
}

ANCRE_IMPORT = "import espace, auth, dossiers, services_cfg, config_projets, admin_projets, admin_comptes, mdp_oublie, opportunites_ui, offres_cfg, devises_cfg, eligibilite, offres_sync, recherche_poste, moteur_plans"
NOUVEL_IMPORT = ANCRE_IMPORT + ", console_accompagnement"

ANCRE_BLOC = """if espace.est_admin() and moteur_plans.ecran(ORIGINES):
    st.stop()"""
NOUVEAU_BLOC = ANCRE_BLOC + """
if espace.est_admin() and console_accompagnement.ecran(D, ORIGINES):
    st.stop()"""

def main():
    # 1+2 : fichiers embarqués
    for rel, info in FICHIERS.items():
        cible = RACINE / rel
        data = base64.b64decode(info["b64"])
        if hashlib.sha256(data).hexdigest() != info["sha256"]:
            sys.exit(f"❌ Empreinte invalide : {rel} — abandon.")
        if info["verif"] == "python":
            ast.parse(data.decode("utf-8"))
        else:
            j = json.loads(data.decode("utf-8"))
            assert len(j["causes_principales"]) == 3
        if cible.exists() and cible.read_bytes() == data:
            print(f"ℹ️  {rel} — identique, déjà en place.")
        else:
            if cible.exists():
                bak = cible.with_name(cible.name + ".bak-installe")
                shutil.copy2(cible, bak)
                print(f"⚠️  {rel} existait → sauvegardé : {bak.name}")
            cible.parent.mkdir(parents=True, exist_ok=True)
            cible.write_bytes(data)
            print(f"✅ Installé : {rel}")

    # 3 : branchement ui.py
    if not UI.exists():
        sys.exit(f"❌ Introuvable : {UI}")
    src = UI.read_text(encoding="utf-8")
    if "console_accompagnement.ecran" in src:
        print("ℹ️  Branchement déjà présent — terminé.")
        return
    if ANCRE_IMPORT not in src:
        sys.exit("❌ Ancre d'import introuvable — le patch moteur_plans "
                 "a-t-il été appliqué ? Abandon.")
    if ANCRE_BLOC not in src:
        sys.exit("❌ Bloc moteur_plans introuvable dans ui.py — abandon.")
    if src.count(ANCRE_IMPORT) != 1 or src.count(ANCRE_BLOC) != 1:
        sys.exit("❌ Ancre non unique — abandon par prudence.")
    bak = UI.with_suffix(f".bak-{datetime.now():%Y%m%d-%H%M%S}.py")
    shutil.copy2(UI, bak)
    nouv = src.replace(ANCRE_IMPORT, NOUVEL_IMPORT, 1)
    nouv = nouv.replace(ANCRE_BLOC, NOUVEAU_BLOC, 1)
    try:
        ast.parse(nouv)
    except SyntaxError as e:
        shutil.copy2(bak, UI)
        sys.exit(f"❌ Syntaxe cassée ({e}) — ui.py restauré.")
    UI.write_text(nouv, encoding="utf-8")
    print(f"✅ ui.py branché (backup : {bak.name})")
    print()
    print("Terminé. Redémarrer :")
    print("  pkill -f streamlit; cd ~/mobilite-ia && streamlit run app/api/ui.py")
    print("Console (admin) :  http://localhost:8501/?page=accompagnement")

if __name__ == "__main__":
    main()
